import axios, { AxiosResponse } from 'axios';
import dayjs from 'dayjs';
import { readFileSync } from 'fs';
import yargs from 'yargs';

const BASE_URL = 'https://powerschoolgroup.atlassian.net';
const argv = yargs.parseSync();

export interface TextParagraph {
  type: 'paragraph';
  content: {
    type: 'text';
    text: string;
    marks?: {
      type?: string;
      attrs?: {
        href: string;
      };
    }[];
  }[];
}

import Joi from 'joi';
const findingSchema = Joi.object({
  disposition: Joi.string(),
  'disposition-owner': Joi.string(),
  'disposition-comment': Joi.string(),
  title: Joi.string().required(),
  issue_id: Joi.number(),
  gob: Joi.string().required(),
  severity: Joi.number().required(),
  issue_type_id: Joi.string().required(),
  issue_type: Joi.string().required(),
  cwe_id: Joi.string().required(),
  display_text: Joi.string().required(),
  files: {
    source_file: {
      file: Joi.string().required(),
      line: Joi.number().required(),
      function_name: Joi.string().required(),
      qualified_function_name: Joi.string().required(),
      function_prototype: Joi.string().required(),
      scope: Joi.string().required()
    }
  },
  flaw_match: {
    procedure_hash: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    prototype_hash: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    flaw_hash: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    flaw_hash_count: Joi.number().required(),
    flaw_hash_ordinal: Joi.number().required(),
    cause_hash: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    cause_hash_count: Joi.number().required(),
    cause_hash_ordinal: Joi.number().required(),
    cause_hash2: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    cause_hash2_ordinal: Joi.string()
      .regex(/[0-9]+/)
      .required()
  },
  flaw_details_link: Joi.string().uri().required()
}).with('disposition', ['disposition-owner', 'disposition-comment']);

export function makeBulletList(listItems: string[]) {
  const ret = {
    type: 'bulletList',
    content: listItems.map((text) => {
      return {
        type: 'listItem',
        content: [
          {
            type: 'paragraph',
            content: [
              {
                type: 'text',
                text: text
              }
            ]
          }
        ]
      };
    })
  };
  return ret;
}

export function makeParagraph(
  title: string,
  content: string,
  url?: string
): TextParagraph {
  const ret: TextParagraph = {
    type: 'paragraph',
    content: [
      {
        type: 'text',
        text: title,
        marks: [
          {
            type: 'strong'
          }
        ]
      },
      {
        type: 'text',
        text: `: ${content}`
      }
    ]
  };
  if (url) {
    ret.content[1].marks = [
      {
        type: 'link',
        attrs: {
          href: url
        }
      }
    ];
  }
  return ret;
}

export interface Disposition {
  type: string;
  owner?: string;
  comment?: string;
}

export function makeTicketDescription(
  disposition: Disposition | undefined,
  cwe_id: string,
  issue_type: string,
  module_url: string,
  source: string,
  display_text: string,
  finding: any
): any {
  const content: any[] = [];
  if (disposition) {
    content.push(makeParagraph('Disposition', ''));
    content.push(
      makeBulletList([
        `Type: ${disposition.type}`,
        ...(disposition.owner ? [`Owner: ${disposition.owner}`] : []),
        ...(disposition.comment ? [`Comment: ${disposition.comment}`] : [])
      ])
    );
  } else {
    content.push(makeParagraph('Disposition', 'N/A'));
  }

  content.push(makeParagraph('CWE', `${cwe_id} ${issue_type}`));
  content.push(makeParagraph('Module', module_url, module_url));
  content.push(makeParagraph('Source', source)); // "src/refarch-project/bin/main.ts:13"
  content.push(makeParagraph('Description', display_text)); // "\u003cspan\u003eThe application contains hard-coded information that may contain credentials to an external service.  The use of hard-coded credentials significantly increases the possibility that the account being protected will be compromised. set\u003c/span\u003e \u003cspan\u003eStore credentials out-of-band from the application code.  Follow best practices for protecting credentials stored in locations such as configuration or properties files.\u003c/span\u003e \u003cspan\u003eReferences: \u003ca href\u003d\"https://cwe.mitre.org/data/definitions/798.html\"\u003eCWE\u003c/a\u003e\u003c/span\u003e"
  content.push(
    makeParagraph(
      'References',
      `CWE-${cwe_id}`,
      `https://cwe.mitre.org/data/definitions/${cwe_id}.html`
    )
  );
  content.push(makeParagraph('Details (DO NOT EDIT)', JSON.stringify(finding)));
  return {
    version: 1,
    type: 'doc',
    content
  };
}

export function makeTicket(
  summary: string,
  epic: string,
  project: string,
  createClosed: boolean,
  severity: number, // Severity as coming from Veracode
  description: {
    [key: string]: any;
  }
): any {
  // Note:
  // - incoming severity is 0 (lowest) to 5 (highest)
  // - Jira ticket priority is reversed; so jira priority = 5-severity
  // - The ticket label has severity level+1
  // Check description is a doc
  if (description.type !== 'doc') {
    throw new Error('ERROR: expected ADF doc for description');
  }
  return {
    update: {},
    fields: {
      summary: summary,
      parent: {
        key: epic // "NFR-779"
      },
      issuetype: {
        name: 'Bug'
      },
      project: {
        key: project // "NFR"
      },
      // NFR number
      customfield_13551: {
        value: '2000'
      },
      // Security related
      customfield_11850: {
        value: 'Yes'
      },
      // Security source
      customfield_14061: {
        value: 'Veracode'
      },
      // Severity
      customfield_10101: {
        value: severity // "2"
      },
      // Phase found in
      customfield_10180: {
        value: 'Sprint Development'
      },
      customfield_10112: [
        {
          value: 'Security'
        }
      ],
      description: description,
      labels: [
        'CWE_798',
        'Sev4_High',
        'veracode-import',
        'veracode-initial-import',
        'vulnerability-backlog',
        ...(createClosed ? ['veracode-false-positive'] : [])
      ]
    }
  };
}

export function getAuth(): { username: string; password: string } {
  const { JIRA_USERNAME, JIRA_PASSWORD } = process.env;

  if (!JIRA_USERNAME || !JIRA_PASSWORD) {
    throw new Error(`need to pass JIRA_USERNAME and JIRA_PASSWORD`);
  }

  return {
    username: JIRA_USERNAME,
    password: JIRA_PASSWORD
  };
}

export async function findTicketByHash(
  project: string,
  hash: {
    procedure_hash: string;
    flaw_hash: string;
    cause_hash: string;
  }
): Promise<AxiosResponse<any, any>> {
  let url = `${BASE_URL}/rest/api/3/search?jql=projectType=software AND project=${project} AND issueType="Bug"`;
  url += ` AND description~"\\"cause_hash\\":\\"${hash.cause_hash}\\""`;
  url += ` AND description~"\\"flaw_hash\\":\\"${hash.flaw_hash}\\""`;
  url += ` AND description~"\\"procedure_hash\\":\\"${hash.procedure_hash}\\""`;
  url += ` and status!="Closed"`;

  const resp = axios.get(url, {
    auth: getAuth()
  });
  return resp;
}

export const BASELINE_DEFAULT = 'veracode_baseline.json';

export interface Finding {
  disposition?: string;
  'disposition-owner'?: string;
  'disposition-comment'?: string;
  cwe_id: string;
  issue_type: string;
  severity: number | string;
  display_text: string;
  flaw_match: {
    procedure_hash: string;
    flaw_hash: string;
    cause_hash: string;
  };

  files: {
    source_file: {
      file: string;
      line: number | string;
    };
  };
}

export async function processFinding(finding: Finding) {
  const query = {
    procedure_hash: finding.flaw_match.procedure_hash,
    flaw_hash: finding.flaw_match.flaw_hash,
    cause_hash: finding.flaw_match.cause_hash
  };

  const today = dayjs();

  const ticket = await findTicketByHash('NFR', query);
  console.log('status', ticket.status);
  if (ticket.status === 200 && ticket.data.issues?.length > 0) {
    console.log(`found it! ${JSON.stringify(query)}`);
  } else {
    const cwe_id = finding.cwe_id;
    const source = `${finding.files.source_file.file}:${finding.files.source_file.line}`;
    const disposition: Disposition | undefined = finding.disposition
      ? {
          type: finding.disposition,
          owner: finding['disposition-owner'],
          comment: finding['disposition-comment']
        }
      : undefined;

    const { JIRA_EPIC, JIRA_PROJECT, CI_PROJECT_URL } = process.env;
    if (!JIRA_EPIC || !JIRA_PROJECT) {
      throw new Error(`requires JIRA_EPIC, JIRA_PROJECT`);
    }

    const module_url = CI_PROJECT_URL || 'unknown'; // This SHOULD always be set in the pipelines
    const ticketDescription = makeTicketDescription(
      disposition,
      cwe_id,
      finding.issue_type,
      module_url,
      source,
      finding.display_text,
      finding
    );

    const newTicket = makeTicket(
      `Veracode static ${source} CWE-${cwe_id} ${today.format('YYYY-MM-DD')}`,
      JIRA_EPIC,
      JIRA_PROJECT,
      disposition != null,
      parseInt(`${finding.severity}`),
      ticketDescription
    );

    const url = `${BASE_URL}/rest/api/3/issue`;

    console.log(`CREATING NEW TICKET to ${url}`, JSON.stringify(newTicket));

    const resp = await axios.post(url, JSON.stringify(newTicket), {
      auth: getAuth(),
      headers: {
        'Content-Type': 'application/json'
      }
    });
    console.log(`response status`, resp.status);
  }
}

export async function lintBaselineFile(filename: string): Promise<void> {
  for (const finding of JSON.parse(readFileSync(filename).toString())
    .findings) {
    // Validate each finding.
    const { error } = findingSchema.validate(finding);
    if (error) {
      throw new Error(error.message);
    }
  }
}

export async function processBaselineFile(filename: string): Promise<void> {
  // Read the file. Errors out if not valid JSON.
  for (const finding of JSON.parse(readFileSync(filename).toString())
    .findings) {
    // Validate each finding.
    const { error } = findingSchema.validate(finding);
    if (error) {
      throw new Error(error.message);
    }
    await processFinding(finding);
  }
}

if (require.main === module) {
  (async () => {
    const fname = (argv.infile ? argv.infile : BASELINE_DEFAULT) as string;
    if (argv.lint) {
      console.log(`linting`);
      await lintBaselineFile(fname);
    } else {
      console.log(`processing`);
      await processBaselineFile(fname);
    }
  })().catch((e) => {
    console.error(e);
  });
}
